// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(); }

    // fuzzed params: two distinct addresses (caller and newOwner) and a bool deciding whether the call is routed through a contract
    function testFuzz_property(address caller, address newOwner, bool viaContract) public {
        // keep addresses non-zero and reasonably wide; allow equality too in domain
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // initial owner is deployer (this contract's address when setUp ran), get it
        address initialOwner = c.owner();

        // Ensure caller has some ETH so they can be used with vm.prank if needed (not strictly needed here)
        vm.deal(caller, 1 ether);

        bool success;

        if (viaContract) {
            // The caller will be a contract which forwards the call to c.setOwner
            // We deploy a forwarder/attacker whose owner of interest (tx.origin) will be 'caller' via vm.prank
            // Attacker.forward will call c.setOwner(newOwner)
            vm.prank(caller);
            // Note: Attacker.forward will use msg.sender = attacker, but tx.origin = caller
            attacker.setupTarget(address(c));
            try attacker.forward(newOwner) {
                success = true;
            } catch {
                success = false;
            }
        } else {
            // Direct EOA call: caller calls c.setOwner
            vm.prank(caller);
            try c.setOwner(newOwner) {
                success = true;
            } catch {
                success = false;
            }
        }

        // single assertion: on the correct contract, only msg.sender (immediate caller) equal to owner may change owner;
        // therefore when the call was made indirectly via a contract (viaContract == true) and the immediate caller
        // was NOT the original owner (attacker contract is caller), the reference C must NOT have changed owner.
        // This property holds for all inputs for the reference; the mutant using tx.origin would allow the change when
        // tx.origin == initialOwner, which the fuzzer can find.

        if (viaContract) {
            // The immediate caller was the attacker contract, so only if attacker contract equals initialOwner should owner change
            // attacker contract is address(attacker), so require that c.owner() == initialOwner (i.e., no change) unless the attacker contract itself was the owner
            // This is the general rule we assert
            assertTrue(c.owner() == initialOwner || address(attacker) == initialOwner);
        } else {
            // direct EOA call: owner may change only if caller == initialOwner
            assertTrue(c.owner() == initialOwner || caller == initialOwner);
        }
    }
}

// helper that forwards calls to C; when invoked by an EOA (tx.origin = that EOA) it becomes the adversarial intermediary
contract Attacker {
    address target;
    function setupTarget(address _t) external { target = _t; }
    function forward(address newOwner) external {
        // forward the call to C; msg.sender here is this contract, tx.origin is the original EOA
        (bool ok, ) = target.call(abi.encodeWithSignature("setOwner(address)", newOwner));
        require(ok, "forward failed");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzer will supply attackerAddr and newOwner candidate
    function testFuzz_property(address attackerAddr, address newOwner) public {
        // Keep admissible domain wide but avoid zero-address newOwner to be meaningful
        vm.assume(newOwner != address(0));

        // Ensure attackerAddr is a contract we deploy (fuzzer gives an address but we must deploy a contract
        // that will call c.setOwner on behalf of its tx.origin). We deploy a small forwarder whose tx.origin
        // is the EOA that initiates the transaction; to simulate that, we will prank from an EOA `EOA` and
        // have that EOA call the forwarder contract which in turn calls c.setOwner(newOwner).

        // Choose an EOA (fuzzed attackerAddr will be used as the EOA here by vm.prank)
        address EOA = attackerAddr;
        // Deploy forwarder that will call c.setOwner
        Forwarder f = new Forwarder();

        // Ensure the starting owner is the test contract deployer (setUp did that). Capture original owner.
        address originalOwner = c.owner();

        // Make sure EOA is not the original owner to create the scenario where msg.sender != owner
        vm.assume(EOA != originalOwner);

        // Fund EOA so it can send txs (not strictly necessary but safe)
        vm.deal(EOA, 1 ether);

        // From EOA, call the forwarder which will call c.setOwner(newOwner)
        vm.prank(EOA);
        // forwarder will perform forwardCall to c
        f.forwardCall(address(c), abi.encodeWithSelector(C.setOwner.selector, newOwner));

        // After that call completes, on the correct contract C (which checks msg.sender==owner) the owner should remain unchanged
        // (because msg.sender in C was the forwarder contract, not originalOwner). This is the universal property.
        assertTrue(c.owner() == originalOwner);
    }
}

contract Forwarder {
    // simple forwarder that calls into target with provided calldata
    function forwardCall(address target, bytes calldata data) external {
        // solhint-disable-next-line avoid-low-level-calls
        (bool ok, ) = target.call(data);
        require(ok);
    }
}

