pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed: address newOwner (may be zero)
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no assumptions so fuzzer can pick zero address
        // act as the deployer/owner (setUp() deploys c by this contract)
        // call setOwner as the owner
        bool ok;
        // this contract is the owner (deployed c in setUp)
        try c.setOwner(newOwner) returns (bool ret) {
            // call succeeded
            ok = ret;
        } catch {
            // if it reverted, mark as false (but reference should not revert)
            ok = false;
        }

        // General rule: For any newOwner and when called by the current owner, setOwner completes and returns true.
        // The reference implementation always returns true on success; the mutant returns false when newOwner == address(0).
        assertTrue(ok);
    }
}

