pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: the new owner address to set. The universal rule: when the caller is the current owner,
    // setOwner succeeds and (in the reference) returns true for every admissible input; the mutant returns false
    // if the new owner is address(0). We let the fuzzer pick the address, including address(0).
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no restrictive vm.assume so that address(0) is allowed

        // make the test caller the current owner (deployer in setUp is owner). Use prank to call as owner.
        bool ok;
        vm.prank(address(this)); // address(this) is not owner; need to prank as the original owner: the deployer is this contract's test runner (tx.origin). However, setUp deployed C from this test contract, so this contract is owner. Ensure call is from this contract.
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // The reference implementation always returns true on success; since call did not revert, the return must be true.
        // Thus assertTrue over c's observed return boolean. This will pass on the reference for all inputs,
        // and fail on the mutant when newOwner == address(0) because mutant returns false.
        assertTrue(ok);
    }
}

