pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: the address to set as owner. The fuzzer will try address(0) among others.
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: allow any address (including zero) — do not exclude the bug-trigger.

        // Ensure the caller is the current owner: c was deployed by setUp (msg.sender == address(this) in setUp),
        // so this test contract is the owner. Use direct call; capture returned boolean via try/catch.
        bool callSucceeded;
        bool returnedTrue;

        try c.setOwner(newOwner) returns (bool ret) {
            callSucceeded = true;
            returnedTrue = ret;
        } catch {
            callSucceeded = false;
            returnedTrue = false; // irrelevant if call reverted
        }

        // Read back the actual owner stored in c via its public getter.
        address actualOwner = c.owner();

        // General property: if the call succeeded, then the returned boolean must equal whether c.owner() equals the provided newOwner.
        // The reference implementation returns true on any successful setOwner and thus this holds (returned == (actualOwner == newOwner)).
        // The mutant returns (_owner != address(0)) which differs when newOwner == address(0): call succeds, actualOwner == address(0), but returned == false, breaking the property.
        if (callSucceeded) {
            assertTrue(returnedTrue == (actualOwner == newOwner));
        } else {
            // If the call reverted, we cannot assert relation about returned value; but reference and mutant both revert only when caller != owner.
            // Since this test contract is the owner, call should not revert for either implementation; keep no assertion on revert path.
        }
    }
}

