pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the new owner address; the fuzzer will try address(0) among others.
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: no vm.assume to allow address(0) through.

        // Caller must be current owner. setUp made deployer the owner (this contract),
        // so prank as address(this) is unnecessary; but to be explicit, use prank.
        bool ok;
        // call setOwner and capture whether it returned or reverted
        vm.prank(address(this));
        try c.setOwner(newOwner) returns (bool ret) {
            ok = true;
            // The single assertion must read c; we assert that the returned boolean equals
            // whether the public getter owner() matches newOwner. This is the universal rule:
            // on the reference, whenever the call returns it reports success (true) iff owner==newOwner.
            // We observe this by checking c.owner() == newOwner implies ret == true, and vice versa.
            // Combine into a single boolean equality and assertTrue on it.
            assertTrue((c.owner() == newOwner) == ret);
        } catch {
            ok = false;
            // If the call reverted, on the correct contract this should not happen when caller is owner,
            // so assert that it did not revert (i.e., ok must be true). This will fail if mutant changes revert behavior.
            assertTrue(ok);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: actor will be the caller (must be current owner), newOwner is the target
    function testFuzz_property(address actor, address newOwner) public {
        // Keep wide domain but ensure actor is a non-zero address we can impersonate
        vm.assume(actor != address(0));

        // make actor the owner: c was deployed by this contract (address(this)), so owner is address(this).
        // We need actor to become owner first so they can call setOwner. Do that by having this contract set owner to actor.
        // address(this) is the current owner now; call setOwner(actor) as this contract (default caller).
        bool ok;
        try c.setOwner(actor) returns (bool r) { ok = r; } catch { ok = false; }
        // The reference always returns true here; mutant also returns true for non-zero actor, but we don't assert it yet.
        // Now impersonate actor and call setOwner(newOwner).
        vm.prank(actor);
        bool ok2;
        try c.setOwner(newOwner) returns (bool r2) { ok2 = r2; } catch { ok2 = false; }

        // General invariant: whenever setOwner completes (does not revert), the returned value is true in the correct contract.
        // So assert that if the call did not revert (ok2 == true means returned true; ok2 == false could mean returned false or reverted).
        // To distinguish revert from a false return, we rely on try/catch: if it returned false, ok2 == false but did not revert.
        // However try/catch here sets ok2==false both for revert and for returned false; to ensure we only assert for non-reverting calls,
        // we must detect revert separately. We re-call without try/catch using low-level call to detect revert vs false return.

        // Detect whether the call reverted by low-level call from actor.
        // Prepare calldata for setOwner(address)
        bytes memory data = abi.encodeWithSelector(c.setOwner.selector, newOwner);
        vm.prank(actor);
        (bool success, bytes memory returnData) = address(c).call(data);

        // The reference contract: whenever the call succeeds (success == true), it returns true (encoded as abi.encode(true)).
        // Therefore we assert that if the call did not revert (success == true), the decoded return is true.
        if (success) {
            // decode return value
            bool returned = abi.decode(returnData, (bool));
            assertTrue(returned);
        } else {
            // if it reverted, we don't assert anything (admissible domain includes reverts)
        }
    }
}
